    if (res.innerText && res.innerText.includes('Sign-in')) {
      captured.push({ method: 'cloneNode', stack: new Error().stack });
    }
    return res;
  };

  const origText = Object.getOwnPropertyDescriptor(Node.prototype, 'textContent').set;
  Object.defineProperty(Node.prototype, 'textContent', {
    set: function(val) {
      check(val, 'textContent');
      return origText.apply(this, arguments);
    },
    configurable: true
  });

  try {
    const sortBtn = document.querySelector('button[aria-label="Sort reviews"]');
    if (sortBtn) sortBtn.click();
  } finally {
    Object.defineProperty(Element.prototype, 'innerHTML', { set: origInnerHTML, configurable: true });
    Node.prototype.cloneNode = origClone;
