const tabId = 343605502;
const result = await browserjs(tabId, () => {
  const btn = document.querySelector('button[aria-label="Sort reviews"]');
  if (!btn) return { error: "no sort btn" };

  const createdNodes = [];
  const observer = new MutationObserver((mutations) => {
    for (const m of mutations) {
      for (const node of m.addedNodes) {
        if (node.nodeType === 1) {
          createdNodes.push({
            tag: node.tagName,
            class: node.className,
            role: node.getAttribute('role'),
            text: node.innerText?.slice(0, 100)
          });
        }
      }
    }
  });
  observer.observe(document.body, { childList: true, subtree: true });

  btn.click();

  // Give it 100ms synchronously if possible or return
  return new Promise((resolve) => {
    setTimeout(() => {
      observer.disconnect();
      resolve({
        createdNodes,
        dialog: document.querySelector('div[role="dialog"]')?.innerText.slice(0, 100),
        menu: document.querySelector('div[role="menu"]')?.innerText.slice(0, 100)
      });
    }, 500);
  });
});
console.log(JSON.stringify(result, null, 2));

