const tabId = 343605502;
const trace = await browserjs(tabId, () => {
  // Dismiss dialog if present
  const dismissBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText.trim() === 'Dismiss');
  if (dismissBtn) dismissBtn.click();

  // Find the dialog container or where it is added
  // Let's see what happens to the DOM when we click
  const sortBtn = document.querySelector('button[aria-label="Sort reviews"]');
  if (!sortBtn) return "sortBtn not found";

  // Let's hook dispatchEvent or EventTarget.prototype.addEventListener
  // Or let's see what happens if we dispatch a native-like MouseEvent with bubbles: true, cancelable: true
  let dialogAppeared = false;
  let stack = null;

  // Let's observe attribute changes on body or elements
  const obs = new MutationObserver((mutations) => {
    for (const m of mutations) {
      if (m.addedNodes) {
        for (const n of m.addedNodes) {
          if (n.innerText && n.innerText.includes('Sign-in to get the best')) {
            dialogAppeared = true;
            stack = new Error().stack;
          }
        }
      }
    }
  });
  obs.observe(document.body, { childList: true, subtree: true });

  sortBtn.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));

  return new Promise((resolve) => {
    setTimeout(() => {
      obs.disconnect();
      resolve({ dialogAppeared, stack });
    }, 200);
  });
});
console.log(JSON.stringify(trace, null, 2));

