const searchResult = await browserjs(tabId, () => {
  const matches = [];
  const seen = new Set();

  function search(obj, path, depth) {
    if (!obj || depth > 5 || seen.has(obj)) return;
    try {
      seen.add(obj);
      for (const key of Object.getOwnPropertyNames(obj)) {
        let val;
        try { val = obj[key]; } catch(e) { continue; }

        if (typeof val === 'string' && (val.includes('Lowest rating') || val.includes('lowest rating') || val.includes('Most relevant'))) {
          matches.push({ path: `${path}.${key}`, val });
        } else if (typeof val === 'object' && val !== null && depth < 4) {
          search(val, `${path}.${key}`, depth + 1);
        }
      }
    } catch(e) {}
  }

  search(window._, 'window._', 0);
  search(window.google, 'window.google', 0);

  return matches;
});
console.log("Found matches in memory:", JSON.stringify(searchResult, null, 2));

