const tabId = 343605502;
const props = await browserjs(tabId, () => {
  const btn = document.querySelector('button[aria-label="Sort reviews"]');
  if (!btn) return "btn not found";

  const allProps = {};
  let cur = btn;
  let level = 0;
  while (cur && level < 5) {
    const p = Object.getOwnPropertyNames(cur).filter(k => !k.startsWith('on') && !k.startsWith('aria'));
    allProps[`level_${level}_${cur.tagName}`] = p;
    cur = cur.parentElement;
    level++;
  }
  return allProps;
});
