const stackTrace = await browserjs(tabId, () => {
  let capturedStack = null;
  const origCreateElement = document.createElement;

  document.createElement = function(tagName, options) {
    const el = origCreateElement.apply(this, arguments);
    const origSetAttr = el.setAttribute;
    el.setAttribute = function(name, val) {
      if (typeof val === 'string' && val.includes('Sign-in to get the best')) {
        capturedStack = new Error().stack;
      }
      return origSetAttr.apply(this, arguments);
    };
    return el;
  };

  const sortBtn = document.querySelector('button[aria-label="Sort reviews"]');
  if (sortBtn) sortBtn.click();

  document.createElement = origCreateElement;
  return { capturedStack };
});
console.log("Captured stack:", stackTrace.capturedStack);

