const tabId = 343605502;
// First dismiss dialog if present
await browserjs(tabId, () => {
  const dismissBtn = document.querySelector('button[jsaction*="dismiss"]') ||
    Array.from(document.querySelectorAll('button')).find(b => b.innerText.trim() === 'Dismiss');
  if (dismissBtn) dismissBtn.click();
});
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1000 });

const fullTrace = await browserjs(tabId, () => {
  let captured = [];

  function check(str, method) {
    if (typeof str === 'string' && (str.includes('Sign-in') || str.includes('Reviews & photos'))) {
      captured.push({ method, stack: new Error().stack });
    }
  }

  const origInnerHTML = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML').set;
  Object.defineProperty(Element.prototype, 'innerHTML', {
    set: function(val) {
      check(val, 'innerHTML');
      return origInnerHTML.apply(this, arguments);
    },
    configurable: true
  });

  const origClone = Node.prototype.cloneNode;
  Node.prototype.cloneNode = function() {
    const res = origClone.apply(this, arguments);
    if (res.innerText && res.innerText.includes('Sign-in')) {
      captured.push({ method: 'cloneNode', stack: new Error().stack });
    }
    return res;
  };

  const origText = Object.getOwnPropertyDescriptor(Node.prototype, 'textContent').set;
  Object.defineProperty(Node.prototype, 'textContent', {
    set: function(val) {
      check(val, 'textContent');
      return origText.apply(this, arguments);
    },
    configurable: true
  });

  try {
    const sortBtn = document.querySelector('button[aria-label="Sort reviews"]');
    if (sortBtn) sortBtn.click();
  } finally {
    Object.defineProperty(Element.prototype, 'innerHTML', { set: origInnerHTML, configurable: true });
    Node.prototype.cloneNode = origClone;
    Object.defineProperty(Node.prototype, 'textContent', { set: origText, configurable: true });
  }

  return { captured };
});
console.log(JSON.stringify(fullTrace, null, 2));

