const tabId = 343605502;
const searchAll = await browserjs(tabId, () => {
  const results = [];

  // Search templates
  document.querySelectorAll('template').forEach(t => {
    if (t.innerHTML.includes('Lowest') || t.innerHTML.includes('Sort')) {
      results.push({ type: 'template', html: t.innerHTML.slice(0, 200) });
    }
  });

  // Search shadow roots
  function walk(node) {
    if (!node) return;
    if (node.shadowRoot) {
      if (node.shadowRoot.innerHTML.includes('Lowest')) {
        results.push({ type: 'shadow', html: node.shadowRoot.innerHTML.slice(0, 200) });
      }
      walk(node.shadowRoot);
    }
    for (const child of node.children) {
      walk(child);
    }
  }
  walk(document.body);

  return results;
});
console.log(JSON.stringify(searchAll, null, 2));

