const dispatcher = await browserjs(tabId, () => {
  // Find where jsaction dispatcher is stored
  // Usually in jsaction.dispatcher or something attached to the root element
  const root = document.querySelector('[jsaction]')?.parentElement;

  // Let's check event listeners on document and window
  // In Chrome DevTools, getEventListeners exists, but in standard page JS, we can check property names
  const winProps = Object.keys(window).filter(k => typeof window[k] === 'object' && window[k] !== null);

  // Let's find any object in window that has keys matching "wfvdle"
  for (const p of winProps) {
    try {
      const obj = window[p];
      for (const k of Object.keys(obj)) {
        if (k.includes('wfvdle95')) {
          return { foundOn: p, key: k };
        }
      }
    } catch(e) {}
  }
  return "not found in top-level objects";
});
console.log(dispatcher);

