// Monitor all nodes added to document during click
const checkNodes = await browserjs(tabId, () => {
  const added = [];
  const observer = new MutationObserver((mutations) => {
    for (const m of mutations) {
      for (const n of m.addedNodes) {
        if (n.nodeType === 1) {
          added.push({
            tag: n.tagName,
            class: n.className,
            role: n.getAttribute('role'),
            text: n.innerText?.slice(0, 50)
          });
        }
      }
    }
  });
  observer.observe(document.body, { childList: true, subtree: true });

  const btn = document.querySelector('button[aria-label="Sort reviews"]');
  if (btn) btn.click();

  observer.disconnect();
  return { added };
});
console.log(JSON.stringify(checkNodes, null, 2));

