const tabId = 343605502;
// Let's scroll the reviews container down to load more reviews
const scrollResult = await browserjs(tabId, async () => {
  // Find scrollable container for reviews
  const pane = document.querySelector('div[aria-label="Global Gas Station"]');
  if (!pane) return "pane not found";

  // Find scrollable element
  const allDivs = Array.from(pane.querySelectorAll('div'));
  const scrollable = allDivs.find(d => {
    const overflow = window.getComputedStyle(d).overflowY;
    return (overflow === 'auto' || overflow === 'scroll') && d.scrollHeight > d.clientHeight;
  });

  if (!scrollable) return "scrollable not found";

  const initialCount = pane.querySelectorAll('div.jJc9Ad, div[data-review-id]').length;

  // Scroll down
  scrollable.scrollTop = scrollable.scrollHeight;

  return {
    initialCount,
    scrollHeight: scrollable.scrollHeight,
    scrollTop: scrollable.scrollTop
  };
});
console.log(scrollResult);
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2000 });

const countAfter = await browserjs(tabId, () => {
  const pane = document.querySelector('div[aria-label="Global Gas Station"]');
  return pane?.querySelectorAll('div.jJc9Ad, div[data-review-id]').length;
});
console.log("Count after scroll:", countAfter);

